import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded character-prefix optimizer with merge-block neighborhood repair."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one scalar like scoring, replacing scalar missing values with ''. """
        try:
            missing = pd.isna(value)
            if not hasattr(missing, "__len__") and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent serialized rows."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested merge groups contiguous while preserving proposed order."""
        if not col_merge:
            return list(order)

        positions = {column: index for index, column in enumerate(order)}
        owners = {}
        claimed = set()

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert integer columns to a valid permutation respecting merge groups."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row using its row-specific column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build frequency-ranked and partial-prefix-ranked global layouts."""
        rows = len(text)
        width = len(columns)
        whole = []
        partial = []

        for column in range(width):
            values = Counter(text[row][column] for row in range(rows))
            mass = sum(
                len(value) * count * (count - 1)
                for value, count in values.items()
            )
            whole.append((mass, len(values)))

            prefixes = Counter()
            for value, count in values.items():
                for length in range(1, min(8, len(value)) + 1):
                    prefixes[value[:length]] += count

            pmass = sum(
                len(value) * count * (count - 1)
                for value, count in prefixes.items()
            )
            partial.append((pmass, len(prefixes)))

        frequency = sorted(
            range(width),
            key=lambda c: (-whole[c][0], whole[c][1], c),
        )
        prefix = sorted(
            range(width),
            key=lambda c: (
                -partial[c][0],
                partial[c][1],
                -whole[c][0],
                c,
            ),
        )

        return [
            self._normalize(columns, frequency, col_merge),
            self._normalize(columns, prefix, col_merge),
        ], frequency

    def _prototype_candidate(self, text, columns, col_merge, base_order):
        """Construct sampled row-specific orders by greedy prototype alignment."""
        rows = len(text)
        width = len(columns)
        fallback = self._normalize(columns, base_order, col_merge)
        result = [fallback[:] for _ in range(rows)]

        if rows < 2 or width < 2:
            return result

        sample_rows = list(range(min(rows, 192)))
        active = base_order[:min(width, 28)]

        def make_string(row, order):
            """Serialize one row under an integer column order."""
            return "".join(text[row][column] for column in order)

        sample_strings = [
            make_string(row, active)
            for row in sample_rows
        ]

        anchors = [0]
        prototypes = [sample_strings[0]]

        while len(anchors) < min(4, len(sample_rows)):
            best_position = -1
            best_distance = -1

            for position, value in enumerate(sample_strings):
                if position in anchors:
                    continue

                nearest = max(
                    self._lcp(value, anchor)
                    for anchor in prototypes
                )
                distance = len(value) - nearest

                if distance > best_distance:
                    best_distance = distance
                    best_position = position

            if best_position < 0:
                break

            anchors.append(best_position)
            prototypes.append(sample_strings[best_position])

        def construct(reference_strings):
            """Assign each sampled row a greedy order against a reference string."""
            orders = [fallback[:] for _ in range(rows)]

            for position, row in enumerate(sample_rows):
                current = sample_strings[position]
                reference = max(
                    reference_strings,
                    key=lambda value: self._lcp(current, value),
                )

                remaining = list(active)
                chosen = []
                cursor = 0

                while remaining:
                    suffix = reference[cursor:]
                    selected = remaining[0]
                    selected_score = -1

                    for column in remaining:
                        score = self._lcp(text[row][column], suffix)
                        if score > selected_score:
                            selected = column
                            selected_score = score

                    chosen.append(selected)
                    cursor += len(text[row][selected])
                    remaining.remove(selected)

                tail = [
                    column for column in base_order
                    if column not in chosen
                ]
                orders[row] = self._normalize(
                    columns,
                    chosen + tail,
                    col_merge,
                )

            return orders

        first = construct(prototypes)
        rebuilt = [
            make_string(
                sample_rows[position],
                first[sample_rows[position]],
            )
            for position in anchors
        ]
        return construct(rebuilt)

    def _repair_blocks(self, text, col_merge, orders):
        """Repair up to 1024 rows using bounded neighbor-based block moves."""
        rows = len(orders)
        if rows < 2:
            return [order[:] for order in orders]

        repaired = [order[:] for order in orders]
        serialized = self._serialize(text, repaired)
        ranked = sorted(range(rows), key=lambda row: (serialized[row], row))

        membership = {}
        for group_id, requested in enumerate(col_merge):
            for column in requested:
                if column not in membership:
                    membership[column] = group_id

        repaired_limit = min(rows, 1024)

        for rank in range(repaired_limit):
            row = ranked[rank]
            old_order = repaired[row]

            blocks = []
            seen_groups = set()

            for column in old_order:
                group_id = membership.get(column)

                if group_id is None:
                    blocks.append([column])
                    continue

                if group_id in seen_groups:
                    continue

                block = [
                    value for value in old_order
                    if membership.get(value) == group_id
                ]
                blocks.append(block)
                seen_groups.add(group_id)

            if len(blocks) < 2:
                continue

            active_count = min(6, len(blocks))
            prefix = blocks[:active_count]
            suffix = blocks[active_count:]

            proposals = []

            for shift in range(1, active_count + 1):
                proposals.append(
                    prefix[shift:] + prefix[:shift] + suffix
                )

            for position in range(1, active_count):
                proposals.append(
                    [prefix[position]]
                    + prefix[:position]
                    + prefix[position + 1:]
                    + suffix
                )

            left = serialized[ranked[rank - 1]] if rank else None
            right = (
                serialized[ranked[rank + 1]]
                if rank + 1 < rows
                else None
            )

            best_blocks = blocks
            best_score = -1

            for proposal in proposals:
                candidate_order = [
                    column
                    for block in proposal
                    for column in block
                ]
                candidate_text = "".join(
                    text[row][column]
                    for column in candidate_order
                )

                score = 0
                if left is not None:
                    score += self._lcp(left, candidate_text)
                if right is not None:
                    score += self._lcp(candidate_text, right)

                if score > best_score:
                    best_score = score
                    best_blocks = proposal

            repaired[row] = [
                column
                for block in best_blocks
                for column in block
            ]
            serialized[row] = "".join(
                text[row][column]
                for column in repaired[row]
            )

        return repaired

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded layout, then apply one merge-block repair pass."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_orders, base_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_orders:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        prototype_orders = self._prototype_candidate(
            text,
            columns,
            col_merge,
            base_order,
        )
        prototype_serialized = self._serialize(text, prototype_orders)
        candidates.append((
            self._reuse(prototype_serialized),
            prototype_orders,
            prototype_serialized,
        ))

        _, incumbent_orders, incumbent_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        repaired_orders = self._repair_blocks(
            text,
            col_merge,
            incumbent_orders,
        )
        repaired_serialized = self._serialize(text, repaired_orders)
        repaired_score = self._reuse(repaired_serialized)
        incumbent_score = self._reuse(incumbent_serialized)

        if repaired_score >= incumbent_score:
            best_orders = repaired_orders
            best_serialized = repaired_serialized
        else:
            best_orders = incumbent_orders
            best_serialized = incumbent_serialized

        row_order = sorted(
            range(rows),
            key=lambda row: (best_serialized[row], row),
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

